🐛 Bug
Tensor.new_ones should be an operator, otherwise there is no way for extension writers to extend it!
To Reproduce
Most of the other new_{blah} methods (Tensor.new_empty, Tensor.new_zeros, ...) are operators.
new_ones is defined here: 


      pytorch/torch/csrc/utils/tensor_new.cpp


        Lines 873 to 886
      in
      1ad06ba







           Tensor new_ones(c10::DispatchKey dispatch_key, at::ScalarType scalar_type, PyObject* args, PyObject* kwargs) { 




             static PythonArgParser parser({ 




               "new_ones(IntArrayRef size, *, ScalarType dtype=None, Device? device=None, bool requires_grad=False)", 




             }, /*traceable=*/true); 









             ParsedArgs<4> parsed_args; 




             auto r = parser.parse(args, kwargs, parsed_args); 




             if (r.idx == 0) { 




               const auto actual_options = typeIdWithDefault(r, 2, dispatch_key); 




               const auto actual_scalar_type = r.scalartypeWithDefault(1, scalar_type); 




               return dispatch_ones(actual_options, actual_scalar_type, r.deviceOptional(2), r.intlist(0)).set_requires_grad(r.toBool(3)); 




             } 




             throw std::runtime_error("new_ones(): invalid arguments"); 




           } 





Not sure if there's a reason why it hasn't been made an operator yet.
cc @gchanan @mruberry

It's very reproducible for me locally with the following code. After removing the .then() callback, it no longer hangs.
import torch
from torch.distributed import rpc
import torch.multiprocessing as mp

import os

def identity(x):
    return x

def run():
    i = 0
    while True:
        x = torch.randn(100, 100)
        futs = []
        for index in range(50):
            futs.append(
                rpc.rpc_async(
                    "server", identity, args=(x,)
                ).then(lambda x: x.wait()) # it no longer hangs after removing this then cb
            )

        torch.futures.wait_all(futs)
        print(f"== round {i}: {futs[0].wait().sum()}")
        i += 1

def run_worker(rank, world_size):
    os.environ['MASTER_ADDR'] = 'localhost'
    os.environ['MASTER_PORT'] = '29500'

    if rank == 1:
        options = rpc.TensorPipeRpcBackendOptions(
                num_worker_threads = 256,
                device_maps={"server" : {0 : 1}}
        )
        rpc.init_rpc("client", rank=rank, world_size=world_size, rpc_backend_options=options)
        run()
    else:
        rpc.init_rpc("server", rank=rank, world_size=world_size)

    rpc.shutdown()


if __name__=="__main__":
    world_size = 2
    mp.spawn(run_worker, args=(world_size, ), nprocs=world_size, join=True)
